['_End Idx'] = N: ['_Leave Idx'] - 1;

['_Hire Idx'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled',
      ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index'),
      IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0,
          DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'), 0 ) );

['_Active'] = N:
