['FTE']       => ['Open Positions'], ['Opening'], ['Closing'];
# Leavers fire the month AFTER headcount drops to 0 — feed forward via Next Period.
['Headcount'] => DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Next Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Leavers'),
                 DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Next Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Closing');

