process::WFP Seed Prior Forecast.PrologProcedure:
#Region WFP Seed Prior Forecast — the forecast as it stood at the Feb 2026 close
# DEMO FABRICATION (there is no time machine for the real Feb forecast).
# Snapshots current Forecast into the static member FCST 2026-02, then scales the
# March (2026-03) cost by +2.5% — "the Feb forecast for March ran 2.5% optimistic;
# actuals came in under". Feeds the Act vs Prior Fcst version member.
# Idempotent — re-run re-snapshots and re-applies the scale.

nRet = ExecuteProcess( 'WFP Snapshot Version', 'pSource', 'Forecast', 'pTarget', 'FCST 2026-02' );
IF( nRet <> 0 );
   ProcessError;
ENDIF;

process::WFP Seed Prior Forecast.EpilogProcedure:
#Region WFP Seed Prior Forecast — Epilog: scale March (member edge now committed)
cWC  = 'WFP Workforce Cost';
cHC  = 'WFP Headcount';
cPos = 'WFP Position';
vTgt = 'FCST 2026-02';
vMar = '2026-03';
nFactor = 1.025;

vPCs  = 'Base|Employer Payroll Tax|Employer Pension|Benefits|Bonus|One-Time|Gross Pay|Employee Income Tax|Employee Pension|Net Pay|';
vMeas = 'Amount|Amount Capex|Amount Opex|';

nB = DIMSIZ( cPos );
nJ = 1;
WHILE( nJ <= nB );
   vPos = DIMNM( cPos, nJ );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      vEnt = ATTRS( cPos, vPos, 'Home Entity' );
      vCC  = ATTRS( cPos, vPos, 'Cost Centre' );
      vSC  = ATTRS( cPos, vPos, 'Salary Currency' );

      vL = vPCs;
      WHILE( SCAN( '|', vL ) > 1 );
         nS = SCAN( '|', vL ); vPC = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
         vCurL = vSC | '|Reporting|Reporting @ Budget FX|';
         WHILE( SCAN( '|', vCurL ) > 1 );
            nS = SCAN( '|', vCurL ); vCurX = SUBST( vCurL, 1, nS - 1 ); vCurL = SUBST( vCurL, nS + 1, LONG( vCurL ) - nS );
            vML = vMeas;
            WHILE( SCAN( '|', vML ) > 1 );
               nS = SCAN( '|', vML ); vMX = SUBST( vML, 1, nS - 1 ); vML = SUBST( vML, nS + 1, LONG( vML ) - nS );
               nCur = CellGetN( cWC, vMar, vTgt, vEnt, vCC, vPC, vCurX, vPos, vMX );
               IF( nCur <> 0 );
                  CellPutN( nCur * nFactor, cWC, vMar, vTgt, vEnt, vCC, vPC, vCurX, vPos, vMX );
               ENDIF;
            END;
         END;
      END;
   ENDIF;
   nJ = nJ + 1;
END;

# Point the March close at its prior-month forecast snapshot (Act vs Prior Fcst
# reads this attr, so it generalises as more snapshots accumulate).
AttrPutS( vTgt, 'WFP Period', vMar, 'Prior Fcst Snapshot' );

ASCIIOUTPUT( 'WFP_PriorForecast_ok.txt', 'FCST 2026-02 seeded; March cost scaled x' | NUMBERTOSTRING( nFactor ) | '; 2026-03 Prior Fcst Snapshot = ' | vTgt );
